#!/usr/bin/env python3
"""Spring quarter shipped-orders reconciliation.

Usage: python3 -I reconcile.py <output-path>
"""
import datetime as dt
import http.client
import json
import sys
import time
import urllib.error
import urllib.request
from collections import Counter
from decimal import ROUND_HALF_UP, Decimal

BASE = "http://localhost:8080"
LOG_PATH = "/tmp/recon-work/fetch.log"
OUT_PATH = sys.argv[1]
RANGE_START = dt.datetime(2025, 3, 1, tzinfo=dt.timezone.utc)
RANGE_END = dt.datetime(2025, 6, 1, tzinfo=dt.timezone.utc)  # exclusive: 31 May inclusive
REGIONS = ("north", "south", "east", "west")
MAX_ATTEMPTS = 60

log = open(LOG_PATH, "w")


def note(msg):
    log.write(time.strftime("%H:%M:%S") + " " + msg + "\n")
    log.flush()


def raw_request(method, path, token=None):
    headers = {"Accept": "application/json"}
    if token:
        headers["Authorization"] = "Bearer " + token
    req = urllib.request.Request(BASE + path, method=method, headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            return resp.status, resp.headers, resp.read()
    except urllib.error.HTTPError as e:
        return e.code, e.headers, e.read()


def retry_delay(headers, body, attempt):
    """Honour the server's own wait hint if it gives one; otherwise back off."""
    header = headers.get("Retry-After") if headers is not None else None
    if header:
        try:
            return float(header)
        except ValueError:
            pass
    try:
        data = json.loads(body)
        for key in ("retry_after", "retry_after_seconds", "retry-after"):
            if isinstance(data, dict) and key in data:
                return float(data[key])
    except (ValueError, TypeError):
        pass
    return min(2 ** attempt, 30)


class Api:
    def __init__(self):
        self.token = None
        self.token_fetches = 0
        self.customers = {}
        self.retry_events = 0

    def fetch_token(self):
        for attempt in range(1, MAX_ATTEMPTS + 1):
            try:
                status, headers, body = raw_request("POST", "/token")
            except (OSError, http.client.HTTPException) as e:
                note(f"token network error attempt {attempt}: {e!r}")
                time.sleep(min(2 ** attempt, 30))
                continue
            if status == 200:
                try:
                    self.token = json.loads(body)["token"]
                except (ValueError, KeyError) as e:
                    note(f"token body unparseable attempt {attempt}: {e!r}")
                    time.sleep(min(2 ** attempt, 30))
                    continue
                self.token_fetches += 1
                note(f"token fetched (#{self.token_fetches})")
                return
            note(f"token status {status} attempt {attempt}: {body[:300]!r}")
            self.retry_events += 1
            time.sleep(retry_delay(headers, body, attempt))
        raise RuntimeError("could not obtain a token")

    def get_json(self, path, auth=True, check=None):
        """GET a JSON document, retrying the same request until it succeeds.

        401/403 means the token has expired: fetch a new one and retry.
        404 on a customer means the id is unknown: return None.
        """
        for attempt in range(1, MAX_ATTEMPTS + 1):
            if auth and self.token is None:
                self.fetch_token()
            try:
                status, headers, body = raw_request("GET", path, self.token if auth else None)
            except (OSError, http.client.HTTPException) as e:
                note(f"GET {path} network error attempt {attempt}: {e!r}")
                self.retry_events += 1
                time.sleep(min(2 ** attempt, 30))
                continue
            if status == 200:
                try:
                    data = json.loads(body)
                except ValueError as e:
                    note(f"GET {path} unparseable body attempt {attempt}: {e!r}")
                    self.retry_events += 1
                    time.sleep(min(2 ** attempt, 30))
                    continue
                if check is None or check(data):
                    return data
                note(f"GET {path} failed validation attempt {attempt}: {body[:300]!r}")
                self.retry_events += 1
                time.sleep(min(2 ** attempt, 30))
                continue
            if status == 404 and path.startswith("/customers/"):
                return None
            note(f"GET {path} status {status} attempt {attempt}: {body[:300]!r}")
            self.retry_events += 1
            if status in (401, 403) and auth:
                self.token = None
                continue
            time.sleep(retry_delay(headers, body, attempt))
        raise RuntimeError(f"gave up on {path} after {MAX_ATTEMPTS} attempts")

    def customer(self, cid):
        if cid not in self.customers:
            self.customers[cid] = self.get_json(f"/customers/{cid}")
        return self.customers[cid]


def fetch_all_orders(api):
    orders = {}
    listings = 0
    dupes = 0
    conflicting_dupes = []
    page_sizes = []
    page = 1
    while True:
        data = api.get_json(
            f"/orders?page={page}",
            check=lambda d, p=page: isinstance(d, dict) and d.get("page") == p and isinstance(d.get("items"), list),
        )
        total_pages = data["total_pages"]
        items = data["items"]
        page_sizes.append(len(items))
        note(f"page {page}/{total_pages}: {len(items)} items, next={data['next']!r}")
        if (data["next"] is None) != (page >= total_pages):
            note(f"WARNING page {page}: next={data['next']!r} disagrees with total_pages={total_pages}")
        for o in items:
            listings += 1
            oid = o["id"]
            if oid in orders:
                dupes += 1
                if orders[oid] != o:
                    conflicting_dupes.append(oid)
            else:
                orders[oid] = o
        if page >= total_pages:
            break
        page += 1
    return orders, listings, dupes, conflicting_dupes, page_sizes, total_pages


def parse_placed_at(s):
    ts = dt.datetime.fromisoformat(s)
    if ts.tzinfo is None:
        raise ValueError(f"naive timestamp, no offset: {s!r}")
    return ts.astimezone(dt.timezone.utc)


def main():
    api = Api()
    orders, listings, dupes, conflicting, page_sizes, total_pages = fetch_all_orders(api)

    # Sanity checks on the fetch itself, before any arithmetic.
    expected_listings = 50 * (total_pages - 1) + page_sizes[-1]
    assert listings == sum(page_sizes) == expected_listings, (listings, sum(page_sizes), expected_listings)
    assert listings == len(orders) + dupes
    assert not conflicting, f"duplicate ids with differing content: {conflicting}"

    status_counts = Counter(o["status"] for o in orders.values())
    print("pages:", total_pages, "listings:", listings, "distinct:", len(orders), "duplicates:", dupes)
    print("status values seen:", dict(status_counts))

    total = 0
    count = 0
    by_region = {r: 0 for r in REGIONS}
    unknown_customers = []
    boundary = []
    offsets = Counter()

    for oid in sorted(orders):
        o = orders[oid]
        if not isinstance(o["amount_cents"], int) or isinstance(o["amount_cents"], bool):
            raise TypeError(f"{oid}: amount_cents is {o['amount_cents']!r}")
        local = dt.datetime.fromisoformat(o["placed_at"])
        if local.tzinfo is not None:
            offsets[str(local.utcoffset())] += 1
        placed_utc = parse_placed_at(o["placed_at"])

        if o["status"] != "shipped":
            continue
        if not (RANGE_START <= placed_utc < RANGE_END):
            continue

        cust = api.customer(o["customer_id"])
        if cust is None:
            unknown_customers.append(oid)
            continue
        pct = cust["discount_pct"]
        if not isinstance(pct, int) or isinstance(pct, bool) or not 0 <= pct <= 100:
            raise ValueError(f"{oid}: discount_pct is {pct!r}")
        region = cust["region"]
        if region not in by_region:
            raise ValueError(f"{oid}: unexpected region {region!r}")

        discounted = int(
            (Decimal(o["amount_cents"]) * Decimal(100 - pct) / Decimal(100)).quantize(
                Decimal(1), rounding=ROUND_HALF_UP
            )
        )
        total += discounted
        by_region[region] += discounted
        count += 1

        # Qualifying orders within a day of either edge of the range.
        if abs((placed_utc - RANGE_START).total_seconds()) < 86400 or abs((placed_utc - RANGE_END).total_seconds()) < 86400:
            boundary.append((oid, o["placed_at"], placed_utc.isoformat()))

    if unknown_customers:
        raise RuntimeError(f"qualifying orders with unknown customers: {unknown_customers}")
    assert total == sum(by_region.values())

    print("customers fetched (distinct):", len(api.customers))
    print("token fetches:", api.token_fetches, "retry events:", api.retry_events)
    print("utc offsets seen:", dict(offsets))
    print("boundary-adjacent qualifying orders:", boundary)

    result = {
        "total_cents": total,
        "order_count": count,
        "duplicates_skipped": dupes,
        "by_region": by_region,
    }
    with open(OUT_PATH, "w") as f:
        json.dump(result, f, indent=2)
        f.write("\n")
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()

